dtsPropsFor.GlassButton:
style?: React.CSSProperties;
  /** Readability only — namespaced per instance before it reaches the registry. */
  id: string;
  onClick: () => void;
  className?: string;
  /** Mirrored to `aria-pressed` — a toggle must say so in the web fallback. */
  pressed?: boolean;
  /** Stand the native glass down and let the web fallback carry the look —
   *  for buttons riding a finger-driven transform, where the async native
   *  mirror visibly trails. */
  suspended?: boolean;
  children: React.ReactNode;
  /** SF Symbol drawn inside the glass. */
  symbol: string;
  /** Set to make it a pill with a word on it instead of a circle with a glyph. */
  title?: string;
  titleStyle?: 'chip' | 'field';
  role?: 'button' | 'chip';
  prominent?: boolean;
  label: string;
  badge?: string;
  badgeTone?: 'primary' | 'danger';
  disabled?: boolean;

dtsPropsFor.GlassGroup:
id: string;
  className?: string;
  itemClassName?: string;
  items: Array<{
    id: string;
    onClick: () => void;
    /** What actually renders in a browser — the native layer draws its own glyph from `symbol`. */
    icon: React.ReactNode;
    /** SF Symbol name for the native iOS 26 glass layer. Invisible on web. */
    symbol: string;
    /** Accessibility label. */
    label: string;
    /** Text shown beside the glyph (native layer only). */
    title?: string;
    titleStyle?: 'chip' | 'field';
    role?: 'button' | 'chip';
    /** Native prominent (tinted-lens) glass. Renders nothing on web. */
    prominent?: boolean;
    /** Fill for prominent glass (native only): 'primary' accent, 'label', or 'white'. */
    tint?: 'label' | 'primary' | 'white';
    /** Small badge on the region, e.g. an unread count (native layer only). */
    badge?: string;
    badgeTone?: 'primary' | 'danger';
    disabled?: boolean;
  }>;

dtsPropsFor.GlassChipRow:
id: string;
  className?: string;
  items: Array<{
    id: string;
    /** SF Symbol for the native capsule. Omit for text-only chips. */
    symbol?: string;
