dtsPropsFor.MichelinMark:
michelin: {
    name: string;
    city: string;
    country: string;
    /** Michelin stars: 1, 2, or 3 for starred restaurants; 0 otherwise. */
    stars: 0 | 1 | 2 | 3;
    /** True for Bib Gourmand entries (good value, no stars). */
    bibGourmand: boolean;
    /** True for "Selected" entries (in the Guide, no star/bib distinction). */
    selected: boolean;
    /** Price tier 1-4 (count of currency symbols in the source). */
    priceTier: number;
    /** Cuisine string, possibly comma-separated ("Modern Cuisine, Creative"). */
    cuisine: string;
    /** Michelin Guide page URL — the value real call sites pass as MichelinBadge's href. */
    guideUrl: string;
    /** Awarded a Michelin Green Star (sustainability). MichelinBadge renders a green leaf for it. */
    greenStar: boolean;
    /** Source coordinates (present for all current records). */
    lat: number;
    lng: number;
  };
  size?: number;
  className?: string;

